def _classifier_kernel(x_ref, w_ref, b_ref, o_ref, acc_ref):
    k = pl.program_id(1)

    @pl.when(k == 0)
    def _init():
        acc_ref[...] = jnp.zeros_like(acc_ref)

    pooled = jnp.mean(x_ref[...], axis=2, dtype=jnp.float32)
    pooled = pooled.astype(w_ref.dtype)
    acc_ref[...] += jnp.dot(
        pooled, w_ref[...], preferred_element_type=jnp.float32
    )

    @pl.when(k == pl.num_programs(1) - 1)
    def _store():
        result = acc_ref[...] + b_ref[...].astype(jnp.float32)
        o_ref[...] = result.astype(o_ref.dtype)


