def workload(x, w, b):
    m, c, h, width = x.shape
    n = w.shape[1]

    bm = 8 if m % 8 == 0 else m
    bc = 128 if c >= 128 and c % 128 == 0 else c
    x_flat = x.reshape(m, c, h * width)

    return pl.pallas_call(
        _classifier_kernel,
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=(m // bm, c // bc),
            in_specs=[
                pl.BlockSpec(
                    (bm, bc, h * width),
                    lambda i, k: (i, k, 0),
